// Original guided explanations. Sources support the mechanisms; worked numbers are teaching examples.
const section=(title,...body)=>({title,body});
const check=(prompt,options,answer,explanation)=>({prompt,options,answer,explanation});
const lesson=(id,title,goal,terms,sections,worked,checks,code,projects,sources)=>({id,title,goal,terms,sections,worked,checks,code,projects,sources,minutes:45});
export const architectureLessons=[
 lesson('foundation','01 · 结构到底决定什么？','沿一条样本，分清任务、结构、训练目标和更新方法。',['transformer','encoder-only','decoder-only','encoder-decoder','hybrid'],[
  section('先认识一条计算链','假设输入是“机械臂 抓取 红色”，模型要预测下一个词。token 是离散的片段编号；embedding 把编号查成一排浮点数。把同一批输入写成 [B,T,D]：B 是样本数，T 是每条样本的位置数，D 是每个位置的特征维度。结构描述这些数经过哪些运算、能访问哪些位置、留下什么中间状态。','一个 Transformer block 通常先让不同位置交换信息（token mixer），再让每个位置独立通过前馈网络 FFN 加工特征。残差把输入加回输出，归一化控制信号尺度。多层 block 后，输出头把特征变成词表上的分数 logits。softmax 才把分数变成概率。'),
  section('四个问题，不能用一个名词回答','“做什么”是任务，例如预测词、预测视频、输出机械臂动作。“怎样计算”是结构，例如 Decoder-only、GQA、MoE。“怎样评判预测”是训练目标，例如交叉熵或去噪误差。“哪些参数能更新”是更新策略，例如全量更新或 LoRA。','SFT 是用输入—示范输出做监督微调；LoRA 是冻结原权重、训练低秩增量的参数化方式。你可以在 Decoder-only 上用 LoRA 做 SFT。把结构改为 KDA 并不能替代标注，也不能自动解决奖励设计。PT 若指 pretraining 是阶段；在未知仓库里仍要确认缩写。'),
  section('从信息可见性理解三种骨干','Encoder-only 常让每个输入位置读取两侧已知输入，适合表示与分类。AR Decoder-only 用因果可见性，位置 t 只能读到不晚于 t 的输入。Encoder–Decoder 先编码源输入，目标侧逐步生成，并通过 cross-attention 读取源表示；这里 Q 来自目标侧，K/V 来自源侧。','AR 是自回归分解方式，不是某一种注意力。Decoder-only 也不是“整个模型只有输出层”。训练时，真实前缀已知，许多位置可以并行计算；推理时，尚未生成的下一步未知，所以通常逐 token 推进。'),
  section('为什么结构常常是组合而不是选一个','一张配置表可以同时写 Decoder-only、GQA、SWA、MoE、RoPE：它们分别描述组织方式、K/V 共享、连接范围、FFN 容量和位置信息。也可以让某些层保留完整注意力，其他层用 SSM 或 KDA。比较时先问改的是哪一层决策。','第一次读模型代码时，只追一条 forward：输入形状 → embedding → 一个 block → 输出头。第二次才追 loss、backward 和 optimizer.step。把每处 shape、mask、状态和可训练参数记下来，比从模型名称猜内部结构可靠。')
 ],{title:'给一个系统贴四种标签',steps:['任务：看机器人历史观测，预测下一步动作。输入先转成 token 或向量。','骨干：因果 Decoder-only；层内 GQA 读取前缀，FFN 加工当前特征。','目标：根据动作表示选择分类交叉熵或连续值回归损失。任务先决定目标是否合理。','更新：用示范数据做监督训练；如果只训练 LoRA 增量，骨干和监督目标并没有因此改变。'],result:'同一个系统有多个互补标签。先确定每个标签回答什么问题，再谈替换与对照。'},[
  check('“Decoder-only + MoE + LoRA SFT”是否矛盾？',['矛盾，只能选择一个','不矛盾，分别描述组织、容量、更新和监督方式','说明完全没有注意力'],1,'Decoder-only 是骨干组织；MoE 常替换 FFN；LoRA 决定可训练增量；SFT 决定监督来源。'),
  check('因果训练能同时计算多个位置，关键条件是什么？',['所有位置都能读取未来答案','每个位置有正确的可见性约束和标签对齐','必须删掉所有 FFN'],1,'并行计算不等于允许读取未来。还要检查输入与标签的移位，不能仅看到三角 mask 就认为无泄漏。')
 ],['arch-window-mask'],['pretrain','sft-lora'],['transformer','t5','llama']),
 lesson('attention','02 · 注意力在读什么，KV 在存什么？','能手算一次读取，并算清 MHA、GQA、MQA 的缓存差别。',['mha','gqa','mqa','mla','flash-attention'],[
  section('Q、K、V 不是三个神秘的数据集','同一个输入向量通常分别乘三个可学习矩阵，得到 query（要找什么）、key（供匹配的特征）、value（真正聚合的内容）。一个 query 与所有可见 key 点积得到分数，经缩放和 softmax 变成权重，最后对 value 加权求和。','假设两个历史 value 是 10 和 20，分数相同，那么权重各一半，结果是 15。若想主要读取第二个，训练需要让相应 Q/K 分数更大；不能直接把 key 当作输出 value。多头把这些读取放到多个特征子空间。'),
  section('为什么要缓存 K/V','生成第 100 个 token 时，前 99 个 token 在某层产生的 K/V 可以复用。缓存避免反复投影旧 token，但当前 Q 仍需读取允许的历史。prefill 指处理已有提示；decode 指继续生成新 token。两种阶段的瓶颈不一定相同。','标准不压缩 KV 的字节数是 B × L × T × hKV × (dk + dv) × 每元素字节数。L 为缓存层数，hKV 为 KV 头数，dk/dv 为单头维度。这只算 K/V；模型权重、激活、临时张量和分配器开销另算。'),
  section('MHA → GQA → MQA：改变的是共享程度','MHA 给每个查询头独立的 KV 头。GQA 把若干 Q 头分组共享一组 K/V。MQA 是所有 Q 头共享一组的端点。查询头数可以保持不变，所以“8 个 KV 头”不等于整个模型只有 8 个头。','共享减少缓存及读取带宽，同时约束表示自由度。不能把某个 MHA checkpoint 改个配置就假定质量保持。实际转换通常需要相应权重处理与训练，也要看 kernel 是否高效支持。'),
  section('MLA 和 FlashAttention 又改了哪里','MLA 把 K/V 信息压到潜在表示中，并结合位置处理和推理计算重排节省缓存；它不是简单地把 KV 头数设为 1。其缓存要根据真实潜在维度、位置分支和实现逐项计算。','FlashAttention 通过分块等方法减少显存读写，计算的仍是注意力。把它与 SWA、GQA 放在一条互斥排行榜上会误导：高效 kernel 可以服务某些结构，但是否支持具体组合仍要核对实现。')
 ],{title:'一眼识别缓存预算',steps:['设 B=1、L=2、T=100、dk=dv=4、FP16 每元素 2 字节。','4 个 KV 头：1×2×100×4×8×2=12,800 字节。','2 个 KV 头：6,400 字节；1 个 KV 头：3,200 字节。','把 T 翻倍，三者都翻倍。共享 KV 并没有把随长度增长的趋势消掉。'],result:'节省的是缓存表示的常数因子。只有进一步限制历史、压缩序列或改为固定状态，长度依赖才可能改变。'},[
  check('GQA 的 Q 头数不变，KV 头从 8 改为 2，其他条件相同，理想 KV 字节数？',['变为四分之一','变为零','保持不变'],0,'公式按 KV 头数计数；这是缓存估算，不能直接推导端到端速度也快四倍。'),
  check('FlashAttention 是否意味着每个 query 只读固定数量的历史？',['是','否，需要另外定义可见位置或稀疏策略'],1,'实现优化与连接结构是不同轴。稠密 FlashAttention 仍计算全可见位置的注意力。')
 ],['arch-kv-budget','arch-sparse-read'],['pretrain','systems'],['transformer','gqa','mqa','mla','flash']),
 lesson('sparse','03 · SWA 到 DSA：到底少读了哪些位置？','画出滑窗与稀疏读取，区分索引分数、注意力分数和缓存。',['swa','longformer','bigbird','nsa','moba','dsa','csa','hca','qsa','msa'],[
  section('先从一个能画出来的窗口开始','SWA 是 Sliding Window Attention，滑动窗口注意力。本课约定 W 包含当前位置。位置 t 可见的范围为 max(0,t−W+1) 到 t。比如 t=5、W=3，只读 3、4、5；0、1、2 即使仍在内存，也不参与这一层的直接读取。','稠密因果注意力对长度 T 产生 T(T+1)/2 个位置对；滑窗产生各位置 min(t+1,W) 的总和。当 T 远大于 W，这个数近似 TW。多层可以通过中间表示传递更远信息，但这不等于当前层直接检索任意远处原始内容。'),
  section('窗口省计算，是否一定省缓存？','只有执行时真正丢弃已不会再读取的旧 KV，滑窗缓存才会被窗口约束。如果实现仍保存全部历史，纸面上的窗口不会自动释放内存。如果某些层是全局注意力，那些层仍要另外计费。','长文本里，刚刚出现的信息适合局部窗口；很早之前给定的编号、约束和跨段引用可能需要远程通路。因此 Longformer 增加全局位置，BigBird 组合局部、随机与全局连接，膨胀或分块方案又选择不同连接模式。没有一种连接规则保证所有远程任务都不受影响。'),
  section('DSA 用学习的索引决定读谁','固定窗口按距离选位置；DSA 的索引器根据内容计算较便宜的相关分数，因果范围内选 top-k，然后主注意力只在这些位置读取。先过滤未来再 top-k，否则高分未来位置会挤掉合法历史，甚至泄漏答案。','索引分数负责选位置，主注意力的 QK 分数负责在所选位置内分配权重；二者不是同一份概率。原始 DeepSeek-V3.2 的主稀疏读取为 O(Tk)，索引计算本身仍有 O(T²) 部分，所以不能把整个系统说成严格线性。稀疏读取也不意味着不保存历史 KV。'),
  section('为什么训练还需要处理索引器','在 V3.2 的公开方案中，先利用稠密注意力信号训练索引器，再转入稀疏阶段；索引器学习匹配注意力分布，主模型继续学习语言目标。离散 top-k 的选择不能简单假设会自动收到普通 softmax 那样的梯度。','浏览器练习只实现因果选择和读取，不训练完整 DSA 索引器。真正复现要追索引损失、梯度边界、初始化与 warmup，以及选错位置后的任务退化。先用可控检索数据验证“该被读的位置有没有进入候选集”。'),
  section('从稀疏走向压缩与混合','块路由如 MoBA 以块为选择单位；NSA 在局部和不同粒度之间组合；CSA 把序列压缩和选择结合；HCA 使用更强的压缩通路。它们改变的粒度、候选表示、训练方法不同，不是把 top-k 改个数就互相转换。','把新论文放进三栏：候选是原 token、块还是压缩表示？谁决定读取集合？遗漏信息怎样补偿？再核对是否保留局部窗口、全局层和原始 KV。目录与模型拆解给出具体版本来源，避免把后续设计套回旧模型。')
 ],{title:'未来高分为什么危险',steps:['位置 t=2，索引分数 [2,9,4,100]，希望选 k=2。','未来位置 3 的分数 100 必须先排除。合法候选为 0、1、2。','按分数选出 [1,2]，再用主注意力自己的分数计算 softmax。','若先在全序列选 [3,1] 再删除未来，只剩一个候选；即使没有泄漏，行为也错了。'],result:'用“未来位置分数极高”的测试捕获选择顺序错误，再用远距离检索任务衡量窗口与选择器的能力差异。'},[
  check('按本课约定，t=5、W=3 可直接读取哪些位置？',['0 到 5','3、4、5','2、3、4'],1,'W 包含当前 token，因此左边界是 t−W+1。实现里若 W 表示左侧跨度，需要显式换算。'),
  check('DSA 每次只选 k 个位置，所以整个模型 KV 内存必为常数？',['正确','错误，选择读取集合与保留历史是两件事'],1,'索引与主注意力通常仍需要历史表示；还要考虑各层类型和真实缓存布局。'),
  check('索引 top-k 的分数能直接当主注意力权重吗？',['可以，都是分数','不能，主注意力需在所选集合上用自身 logits 归一化'],1,'索引器的目标是挑选候选。选择后计算主注意力，才得到对 value 的聚合权重。')
 ],['arch-window-mask','arch-causal-topk','arch-sparse-read'],['memory','systems'],['mistral','longformer','bigbird','dsa','nsa','moba','v4']),
 lesson('alternatives','04 · 近似路线：究竟近似了哪一步？','辨别长度投影、核映射、地标和哈希分组。',['linformer','performer','nystrom','reformer','linear'],[
  section('为什么还要近似，而不是只删连接','全注意力的一个难点是 T×T 的交互矩阵。有些方法不直接决定哪些原位置留下，而是改变这个矩阵的表示或计算顺序。注意力可以写成带归一化的相似度加权和；不同近似在不同环节改变它。','先分清精确等价和近似：FlashAttention 在支持的设置下以更高效的方式计算同一注意力；低秩、核近似通常引入表达假设或误差。更省资源并不代表对每个输入都得到同样的数值。'),
  section('四条路线逐个拆开','Linformer 在序列维度压缩 K/V，让查询读取较少的投影表示。Performer 用随机特征近似 softmax kernel，让一些计算可以重排。Nyströmformer 用少量地标近似注意力矩阵。Reformer 利用 LSH（局部敏感哈希）把可能相关的位置放在候选桶里。','投影维度、随机特征数、地标数和桶大小都是质量—成本旋钮，但含义不同。不要只设相同数字就认为公平：应比较实际内存、耗时、误差和下游任务质量。'),
  section('从核映射走到线性注意力','若相似度写为 phi(q) 与 phi(k) 的内积，就可能先累计 key/value 的外积状态，再让 query 读取。因果版本只能累计当前与过去，且某些形式还有用于归一化的额外状态。','“线性”通常说序列长度方向的计算或存储增长，不代表模型没有非线性，也不意味着所有方案都精确等价于 softmax。小矩阵状态可能有容量瓶颈；长度变长时更快，也可能更难记住大量精确对应。'),
  section('怎样做第一场有意义的比较','先生成短序列，用稠密注意力作参考，比较近似输出的误差。固定输入与权重，逐渐增加近似预算。接着再训练同一小任务；前向误差小并不保证训练后质量最好，反之模型也可能适应近似。','最后测两种任务：局部模式预测和远处键值检索。记录随机种子；随机特征与哈希本身会带来波动。不要把一次短输入运行结果推广到长上下文生产环境。')
 ],{title:'选择近似预算',steps:['固定 64 个 token 与同一组 Q/K/V，先保存稠密输出作为参考。','逐个改变投影维度或特征数，例如 8、16、32；一次只改一个方法的预算。','记录输出误差、峰值内存、耗时。小样本中框架开销可能淹没算法差异。','在相同数据上重新训练，再报告任务效果；分开报告“算子近似误差”和“任务质量”。'],result:'结构比较需要机制证据和任务证据，两者不能互相替代。'},[
  check('Performer 与 FlashAttention 的主要区别？',['前者涉及 kernel 近似，后者侧重同一注意力的高效计算','两者都是固定滑窗','两者都只减少专家数量'],0,'要区分改变计算函数与优化其执行。精确性仍需说明数值精度及支持的设置。'),
  check('随机特征数增加后一次实验更好，下一步是什么？',['宣布全面超过所有结构','重复种子并检查误差、资源与任务质量','删除稠密基线'],1,'近似预算影响多个指标，单次结果不足以判断稳定收益。')
 ],[],['memory','systems'],['linformer','performer','nystrom','reformer','linear']),
 lesson('state','05 · SSM、S4、Mamba：把历史变成状态','亲手更新状态，理解选择性与固定记忆的收益和限制。',['rnn','ssm','s4','mamba','mamba2','mamba3','rwkv','hyena','transformer-xl'],[
  section('先不看论文：你真的需要保存每次输入吗','假设只要估计一个平滑趋势，可以维护 h_t=0.8h_(t−1)+x_t。新输入来时，旧状态衰减，再加入当前值。状态 h 是推理时随序列变化的记忆；系数 0.8 可以看作参数。训练更新参数，读入新 token 更新状态，这是两个不同过程。','这种递推不必保存所有旧 x，但也无法从单个 h 无损恢复全部历史。固定大小状态适合压缩与持续更新；精确查找任意旧记录可能更困难。比较状态路线与完整 KV 路线时，这是首先要理解的取舍。'),
  section('SSM 的三个矩阵各做什么','离散状态空间模型可以写为 h_t=A_t h_(t−1)+B_t x_t，y_t=C_t h_t；某些实现还包含直连项 D x_t。A 控制已有记忆怎样演化，B 把新输入写入状态，C 从状态读出输出。多维状态允许不同分量有不同衰减或交互。','SSM 是建模家族，不是一个单独的 checkpoint；RNN 是更广的循环计算概念，两者有联系但不能当同义词。Dreamer 的 RSSM 还包含随机潜状态等设计，也不能看到三个相近字母就当成 Mamba 层。'),
  section('S4 为什么强调结构化','直接学习和计算任意大状态矩阵可能很贵，长序列也可能难以稳定保留信息。S4 研究结构化状态空间参数化和高效计算，使长程动态可训练。在适用的线性时不变情形，递推与卷积视角能够联系起来。','“能写成递推”不意味着训练一定用 Python 逐 token for 循环。可以利用卷积、扫描或分块算法。但并行训练与逐步推理必须计算相容的函数，测试时要比较两种执行方式的输出。'),
  section('Mamba 增加了依输入而变的选择性','固定衰减对任何输入都执行同样规则；选择性机制让部分状态更新参数随当前内容变化。直觉上，模型可以学着对不同输入保留、写入不同信息。这种内容选择使高效 scan 和内核实现成为关键。','Mamba-2 用结构化状态空间对偶性连接特定 SSM 与注意力形式，并改进计算组织；它不是说任意 softmax Transformer 都和任意 SSM 完全相同。Mamba-3 进一步研究离散化、复数状态及多输入多输出设计。先掌握状态更新，再把这些后续工作当作扩展。'),
  section('与其他记忆路线放在一起看','RWKV 结合循环推理与可并行训练的设计；Hyena 用长卷积与门控组织信息混合；Transformer-XL 保存片段记忆供后续读取。它们共同面对长上下文成本，但保存什么、怎么写、怎么读都不一样。','学习优先级：先实现一维 SSM，再验证分段处理与一次处理一致，再读 S4/Mamba 的选择性和实现。接着学习 DeltaNet/KDA 的纠错写入。固定状态的字节数还受层数、通道数、状态维度与 dtype 影响，不是“没有缓存”。')
 ],{title:'一阵脉冲留下了什么',steps:['初态 h=0，系数 a=0.8，输入序列 [1,0,0,0]。','第 1 步 h=1；随后得到 0.8、0.64、0.512。记忆逐渐衰减。','把 a 改成 0，输入结束后立刻忘掉；改成 1，旧脉冲会持续保留。','处理另一条独立样本时必须重置状态。若从 0.512 接着算，样本之间会相互污染。'],result:'先看清状态的数值轨迹，再讨论长序列能力。浏览器中的标量实验只展示 SSM 机制，不是完整 Mamba 复现。'},[
  check('新 token 进入模型后，隐藏状态变化是否等于模型参数被训练了？',['是，每一步都在反向传播','否，推理中的状态更新也会发生'],1,'区分参数、优化器状态和序列记忆。普通推理不需要执行 optimizer.step。'),
  check('固定大小状态意味着什么？',['能无损记住任意多独立记录','状态预算不随序列长度增长，但可能存在信息压缩损失','整个模型没有显存开销'],1,'状态维度固定不代表记忆无限；还要算参数、激活及混合层的 KV。'),
  check('把一条序列分成两段处理，要怎样与整段结果一致？',['每段都把状态归零','把前段末状态传给后段，并保持相同计算规则','把下一条独立样本状态传入'],1,'连续片段应传递状态；独立样本应重置。训练时是否 detach 是另外一个梯度边界问题。')
 ],['arch-ssm-scan'],['memory','world-model'],['s4','mamba','mamba2','mamba3','rwkv','hyena']),
 lesson('delta','06 · DeltaNet → GDN → KDA：记错了怎样修改？','逐项解释遗忘、旧预测、误差写入和新状态读取。',['linear','deltanet','gdn','kda','gdn2','gla','retnet','hybrid'],[
  section('累加记忆为什么会相互干扰','把 key/value 写进矩阵状态的简单方式是累加外积 k vᵀ。一个 key 再次出现但 value 改变时，旧记录可能仍留在状态里。你真正想做的常常是先看当前记住了什么，再按误差修正。','Delta rule 就采用这种纠错思路：用 key 从旧状态读出预测，与当前 value 比较，只写入差值。不是每次覆盖整张矩阵，也不是对每个历史 token 重新算完整 softmax。'),
  section('先固定矩阵朝向，再看公式','本课 S 的形状为 [dk,dv]，k/q 长度 dk，v 长度 dv。先遗忘：A=diag(alpha)S；再读取：pred=Aᵀk；算误差：error=v−pred；写入：S_new=A+beta·k·errorᵀ；最终输出：o=S_newᵀq。','beta 控制当前纠错强度。DeltaNet 的基本形式没有额外的遗忘门；Gated DeltaNet 增加标量衰减；KDA 使用更细粒度的通道衰减 alpha。这里展示核心递推，完整模型还包含投影、归一化、卷积、门值参数化和高效 kernel。'),
  section('为什么先遗忘再计算纠错','如果先用未衰减的旧状态预测，再去衰减，会把不同时间的状态混在一起。按本课公式，纠错应针对已经遗忘后的 A。通道门可以让不同记忆方向有不同保留程度，但学习出合适的门仍依赖数据与目标。','GDN2 等后续研究继续区分遗忘、擦除和写入的门控自由度。更多自由度意味着更多设计与优化选择，并非只要门变多就保证任务收益。比较这些变体时应先保持状态维度和训练预算可比。'),
  section('为什么 KDA 经常和注意力混合','状态压缩有助于长序列计算，但有些任务需要精细检索旧 token。Kimi Linear 的公开组合使用 KDA 与 MLA 层，以补充不同能力。因此 KDA 是组件名称，不能等同于整个 Kimi 系统。','DSA 在历史候选中挑选读取位置，KDA 将信息持续写入矩阵状态。二者解决同一个长序列问题的不同部分，缓存、训练与信息损失方式不同。先做键值检索、长程约束和持续更新三类任务，再决定组合比例。')
 ],{title:'完整算一次二维 KDA 核心更新',steps:['S=[[2,0],[0,4]]，alpha=[0.5,1]，k=[1,0]，v=[5,1]，beta=0.5，q=[1,1]。','按行衰减得到 A=[[1,0],[0,4]]；pred=Aᵀk=[1,0]。','error=[4,1]；beta·k·errorᵀ=[[2,0.5],[0,0]]。','新状态 [[3,0.5],[0,4]]；用 q 读取，输出 [3,4.5]。'],result:'在互动实验里把 beta 设为 0：只遗忘、不写入。把 alpha 设为全 1：取消遗忘。先预测输出，再运行代码验证。'},[
  check('本课递推的 pred 应从哪里读？',['未衰减的 S','衰减后的 A','未来 token 的 KV'],1,'纠错针对更新前、已遗忘的状态。公式中的运算顺序不可随意交换。'),
  check('KDA 与 DSA 最关键的区别是什么？',['都是同一个 top-k 算法','前者维护矩阵状态，后者选择历史位置读取','一个用于训练，一个只能推理'],1,'两者都可用于训练和推理；区别在于保存与读取历史信息的结构。'),
  check('含 KDA 与 MLA 的混合模型，总缓存能直接算成纯 KDA 状态吗？',['能','不能，仍要逐层加入 MLA 等缓存'],1,'整体成本需要所有层、卷积状态、dtype 与实际实现共同决定。')
 ],['arch-gated-delta'],['memory','omnifm'],['delta','gdn','kda','gdn2','kimi']),
 lesson('capacity','07 · MoE、位置与残差：一层不只有注意力','分清路由参数、传递顺序和维持信号的不同角色。',['dense-ffn','swiglu','moe','shared-experts','engram','rope','alibi','norm','residual','mhc'],[
  section('FFN 为什么占据大量参数','注意力解决不同位置之间的交互，FFN 通常逐位置把 D 维特征扩展到更宽的中间维，再投影回来。它使用共享的参数，但同一层里不同 token 的 FFN 计算不需要彼此相连。SwiGLU 加入门控乘法来控制特征通道。','因此更换注意力后，不能假定总参数或总 FLOPs 同比例减少。要分别统计 embedding、mixer、FFN、输出头及共享权重；大量成本可能仍在 FFN。'),
  section('MoE 选择的是专家，不是历史位置','稀疏 MoE 常用路由器为每个 token 选择少量专家 FFN。总参数量计算所有专家，激活参数量只算当前路径及共享组件。DSA 选择历史 token，MoE 选择参数模块；可以出现在同一模型里。','收益是有机会在每 token 计算受控时扩大容量；代价包括负载不均、跨设备通信、容量限制和路由训练。真实吞吐不只由激活参数决定。共享专家可提供常用处理路径，但它们的计算也必须算入。'),
  section('位置、归一化、残差分别管什么','如果没有位置线索，单纯集合式相似度难以表达先后顺序。RoPE 通过旋转表示将位置信息纳入注意力，ALiBi 用与距离有关的偏置影响分数。外推到更长长度仍需验证，不是换一个编码名称就无限上下文。','归一化控制特征尺度，残差提供信号和梯度的直接路径。RMSNorm、Pre/Post Norm、普通残差与 mHC 等连接设计属于不同的稳定性与信息传递选择。它们影响训练行为，不能只比较参数量。'),
  section('怎样避免“一个新结构包治百病”','先看瓶颈：是知识容量不足、token 路由倾斜、梯度不稳还是读不到远处信息？MoE、Engram 式条件记忆、残差改造与稀疏注意力针对的部位不同。必须给出与症状对应的证据。','一次实验只改一个关键变量。MoE 先记录每个专家分到多少 token，再谈质量；长上下文先做长度外推测试，再谈位置编码；训练不稳先检查数值、初始化、学习率与梯度，再决定是否更换残差结构。')
 ],{title:'小模型也能看见负载不均',steps:['4 个专家、4 个 token，每个 token 选 2 个专家。','路由分别为 [0,1]、[0,1]、[0,2]、[0,3]。','计数为 [4,2,1,1]，共 8 次分配，均匀目标为每个 2 次。','专家 0 可能成为瓶颈；仅说“每次只激活两个专家”没有揭示这一问题。'],result:'先实现负载统计，再把真实路由日志接入。负载均匀也不能单独证明质量好。'},[
  check('MoE top-k 与 DSA top-k 分别选择什么？',['专家与历史位置','都是模型层','都是词表 token'],0,'同样叫 top-k，不代表操作对象相同。MoE 路由到参数模块；DSA 选择可读取的历史候选，二者可以同时存在。'),
  check('总参数 80B、每次激活 3B，能直接断言显存只需存 3B 吗？',['能','不能，未激活专家仍需存储或调度'],1,'权重驻留、卸载、通信、激活和缓存都要计入部署方案。')
 ],['arch-moe-load'],['pretrain','systems'],['moe','mixtral','swiglu','rope','alibi','mhc','engram']),
 lesson('vision','08 · 视觉塔、DINO 和跨模态接口','把图像到语言或动作的路径拆成可检查的模块。',['cnn','vit','swin','dino','clip','siglip','connector','resampler'],[
  section('像素怎样变成 token','一张 RGB 图是 [H,W,3]。ViT 把图切成 patch，每块展平后投影成 D 维向量，再用 Transformer 混合。若图像 224×224、patch 16×16，就有 14×14=196 个 patch token；特殊 token 另计。','CNN 用局部卷积与层级特征提取空间模式；Swin 在局部窗口中做注意力并通过移位等设计交换信息。视觉结构的局部性与文本因果性不是同一约束：一张已知图片通常可以读取整张图。'),
  section('DINO 不是一种新的 token 形状','DINO 系列研究自监督视觉表示学习。模型从图像训练出特征，而无需把每张图都标成文本指令。具体版本的骨干和训练配方要看公开模型卡；“DINO 视觉塔”通常是把某个 DINO checkpoint 当作图像编码器。','CLIP/SigLIP 使用图像—文本配对目标学习跨模态对齐，和 DINO 的监督来源不同。不能因为都能输出向量就认为它们对定位、密集预测、检索和语义理解同样好。选择视觉塔应由下游数据与指标决定。'),
  section('连接器把两个世界接起来','视觉特征可能是 [B,196,768]，语言模型需要 [B,T,1024]。线性层或 MLP connector 可以把通道维从 768 映射到 1024；resampler 还可能用固定数量查询压缩 token 数。维度对齐只是第一步，语义对齐还需要训练。','冻结视觉塔意味着不更新它的权重，不代表不计算特征。若提前缓存特征，图像增强、分辨率、checkpoint 和预处理发生变化时，缓存可能失效。先检查这些接口，比盲目解冻整个模型更有效。'),
  section('为 OmniFM 画一条真实数据流','从一帧样本开始，记录 resize/crop/归一化 → 视觉编码器 → 选择哪些层或 token → connector → 时序骨干 → 预测头。对每个箭头写输入输出 shape、mask、dtype 和是否有梯度。','首先做单样本过拟合与冻结特征的小基线。再比较 DINO 与图文对齐塔、token 压缩比例、冻结与解冻，固定数据划分和训练预算。项目入口保留源码阅读任务，不能用通用名称代替对实际配置的确认。')
 ],{title:'196 个视觉 token 到 32 个条件 token',steps:['224×224 图像切 16×16 patch，得到 196 个位置。','视觉塔输出 [B,196,768]。线性 connector 后变成 [B,196,1024]。','若 resampler 输出 32 个查询表示，则可变成 [B,32,1024]。','序列变短节省后续处理，但空间细节可能损失；用定位或动作任务验证，而不是只看张量能拼接。'],result:'结构选择落在明确接口上：通道变换、token 数压缩、监督对齐与梯度路径分别检查。'},[
  check('把视觉特征维度投影到语言维度，是否自动完成语义对齐？',['是','否，形状兼容不等于语义可用'],1,'需要合适数据、训练目标和评测确认语言或动作头能使用这些特征。'),
  check('DINO 与 ViT 是怎样的关系？',['互斥，二选一','表示学习方法/模型家族与可使用的骨干是不同层级'],1,'先查具体 checkpoint 的骨干与训练配方，不能仅凭 DINO 标签判断全部结构。')
 ],[],['vision','omnifm'],['vit','swin','dino','clip','siglip','llava','perceiver']),
 lesson('generation','09 · U-Net、DiT、视频与扩散语言模型','分开生成目标、数据表示、网络骨干与采样器。',['vae','unet','dit','mmdit','video-mixer','diffusion-lm'],[
  section('生成系统有四个可独立问的问题','在什么空间生成：像素、潜变量还是离散 token？预测什么：噪声、速度、干净样本或下一个 token？用什么网络：U-Net、DiT 或其他骨干？如何采样：一步步加 token，还是逐步去噪？这四个问题相互约束，但不是同义词。','预训练 PT 是训练阶段，AR 是概率分解，diffusion/flow 描述目标与生成过程，DiT 描述一种骨干组织。看到一个生图团队的缩写，先找到它对应的 loss、模型类或采样函数，避免把内部简称当成通用结构。'),
  section('U-Net 与 DiT 为什么都能做去噪','U-Net 通过下采样、上采样与跳连结合多尺度信息。DiT 将图像潜表示切成 token，用 Transformer block 处理，并注入时间及其他条件。二者都可以输出与去噪目标相容的张量，但计算组织和归纳偏置不同。','VAE 等压缩器把高分辨率像素转成较小潜空间，降低后续生成成本；重建误差也形成上限。不要把生成模糊全部归因于去噪骨干，先看压缩器单独重建是否已经丢失细节。'),
  section('条件和时间怎样进入网络','时间步告诉网络当前噪声程度；文本或图像条件告诉它生成什么。条件可经 cross-attention、调制层或联合序列交互进入。MMDiT 对多模态流作特定设计，不能把任何拼接文本的 DiT 都叫同一个实现。','视频还增加时间维。全时空交互、空间/时间分解和局部窗口有不同成本与连贯性取舍。重复帧、时间错位、动作条件未对齐等数据问题，也会看起来像结构缺陷。'),
  section('文本也不一定逐 token AR 生成','扩散语言模型探索迭代恢复离散序列等生成方式。其注意力可见性、训练破坏过程和采样策略要联合理解，不能只把因果 mask 删掉就认为获得等价能力。','第一项实验应小到能排查：固定数据、编码器、目标与采样预算，只换小 U-Net/DiT 骨干；再单独研究目标与采样器。报告训练耗时、采样延迟和质量，多步生成的步数必须写清楚。')
 ],{title:'为什么“换成 DiT”还没有定义完整实验',steps:['固定一批简单形状图像和训练/验证划分。','先确定像素空间还是固定的潜空间，选择同一噪声目标和条件。','在匹配预算的小 U-Net 与小 DiT 上训练，使用同一采样设置。','再分别增加采样步数，记录质量与总生成时间；不要用一个 50 步模型和另一个 5 步模型只比质量。'],result:'把目标、表示、骨干和采样器写进实验表，才能判断改进来自哪里。'},[
  check('DiT 这个词是否完整说明损失和采样步数？',['是','否，它主要描述骨干，仍需查看训练与采样配置'],1,'同一骨干可以搭配不同目标、条件与采样设置。'),
  check('生成细节很差，最先排查压缩器有什么价值？',['没有价值','压缩器重建已丢失的信息，后续生成不能简单当作骨干问题'],1,'分别测表示重建和生成任务，能定位误差来源。')
 ],[],['flow','vision'],['unet','ldm','dit','mmdit','llada']),
 lesson('embodied','10 · 世界模型与具身策略：预测和行动怎样接上','理解 RSSM、JEPA、VLA、动作专家与 rollout 的关系。',['rssm','jepa','vla','action-expert','diffusion-policy','act'],[
  section('先明确输出是环境还是动作','世界模型用历史及动作预测未来环境表示；策略从观测、目标等输入生成行动。一个系统可以同时有二者，也可能只训练策略。Decoder-only、SSM、DiT 都可能成为局部组件，单靠骨干名字不能判断整个系统是否是世界模型。','one-step 是给定真实历史预测下一步；rollout 是把自己的预测继续作为后续输入。前者很好、后者漂移，是常见现象。训练评测必须区分这两种输入分布。'),
  section('RSSM 与 JEPA 分别强调什么','Dreamer 系列使用带确定性与随机潜状态的 RSSM 建模动态，并在潜在想象中学习行为。这里的随机潜状态、观测编码和训练目标共同构成系统，不只是一个 SSM mixer。','JEPA 强调在表示空间预测目标表示。视频 JEPA 关注时空表示及其预测；是否包含动作条件、怎样训练与用于规划，要看具体版本。它不等于逐像素生成视频，也不能用视觉观感直接代替其任务评价。'),
  section('VLA 与动作头有多种组合','VLA 表示视觉—语言—动作接口。图像和指令进入表示骨干后，动作可以被离散成 token，也可以由连续动作头、扩散或 flow 模块生成。动作专家可以独立组织动作侧计算，并通过条件读取感知表示。','ACT 预测一段动作块；Diffusion Policy 迭代生成连续动作序列。块长度影响延迟、平滑性与反馈频率。离线误差低也可能在闭环执行中失败，要考虑执行频率、控制接口和环境反馈。'),
  section('OmniFM 源码必须落到证据','从项目入口指定的一条配置开始，追 dataset、collator、model.forward、loss、optimizer、checkpoint、eval。记录实际启用的视觉塔、时序模块、动作条件与预测目标。仓库支持某模块，不等于本次训练用了它。','做逐步优化：先建立简单预测基线 → 单样本过拟合 → 小规模训练与验证 → 加动作条件 → 多步 rollout → 替换 mixer → 做消融。每次写“症状、假设、唯一变量、结果、下一步”，把结构知识变成可复核的迭代能力。')
 ],{title:'预测误差低但不能规划，怎么诊断',steps:['先测真实历史条件下的一步预测，确认编码和标签时间对齐。','再用预测结果连续 rollout 5、10、20 步，画误差随步数变化。','固定初始观测，替换动作序列，检查预测是否对动作产生合理差异。','若动作怎么换都一样，优先检查动作条件和数据；不是立即换更大的 KDA 或视觉塔。'],result:'结构改动应回应已经定位的失败模式。把图、配置、种子和失败样例一起保留，才形成转岗作品证据。'},[
  check('一套系统能预测未来图像，是否足以证明它能规划动作？',['足以','不足，还要验证动作条件、rollout 与决策使用'],1,'观察预测质量与控制用途不是同一个指标。还要确认预测随动作合理变化，并能支持闭环决策；只看生成画面不足以验证这些能力。'),
  check('源码里存在 KDA 类，能否证明当前训练使用 KDA？',['能','不能，要追实际配置和实例化路径'],1,'必须确认运行时模块、层数、条件和 checkpoint；支持与启用需要分开记录。')
 ],[],['world-model','planning','omnifm'],['dreamer','jepa','openvla','pi0','diffusionPolicy','act']),
 lesson('evaluation','11 · 做一次能解释的结构对照','用可比预算、任务与成本证据回答“为什么这样设计”。',['flash-attention','paged-attention','streaming','mtp','hybrid'],[
  section('先写假设，不要从榜单选答案','假设是“局部模式为主，窗口化可以减少成本且不明显损害任务”，而不是“新论文一定更好”。选一组能证伪的任务：局部预测、远距离键值检索、跨段约束和持续更新。每种结构可能在不同任务上暴露缺陷。','保留稠密基线和简单基线。第一轮统一数据划分、token 预算、优化器、种子与评测流程；参数量与计算量通常无法同时完全相同，明确主要匹配哪一项，并列出其余差异。'),
  section('训练效率和推理效率分别测','训练记录吞吐、峰值显存、loss、验证指标与稳定性。推理区分 prefill 与 decode，记录 prompt 长度、输出长度、batch、dtype、硬件和 kernel。暖机、同步计时与多次重复很重要。','本模块预算器只算理想状态字节数与位置对，不能替代 H20 或 Mac 上的实测。固定状态路线也有投影、FFN、scan 和 kernel 开销；稀疏方案也有索引、路由及通信成本。'),
  section('执行优化不能伪装成结构收益','PagedAttention 管理 KV 的存储与调度，FlashAttention 优化注意力 IO，量化改变表示精度，推测解码尝试减少主模型串行步数。它们可能和结构组合，但需要分别记录。MTP 是多 token 预测相关设计，是否用于推测以及是否保持目标分布由完整算法决定。','StreamingLLM 的 attention sink 与保留近邻策略也有具体条件，不等同于训练时的 SWA。修改缓存保留规则后，要重新检查任务退化与位置处理。模型会运行，并不代表函数或任务表现保持不变。'),
  section('把一次对照整理成可答辩作品','最小报告包含：问题与假设、数据来源和切分、结构示意、参数与预算表、训练曲线、主指标与分组指标、失败样例、运行命令和版本。为每个结论指出证据所在，不只展示最好一次截图。','先用浏览器机制题排除 mask、top-k、状态更新错误，再到 P07/P09 做训练和系统实验，最后在 P10 对照 OmniFM。广泛目录提供检索地图；三个月的深度优先放在能跑通和讲清的核心对照，不把读完目录当成已经复现所有模型。')
 ],{title:'一份最小对照矩阵',steps:['候选：稠密注意力、SWA、状态 mixer、混合层；使用相同样本和固定验证集。','任务：局部模式与远程检索各一组，长度至少两档。','结果：质量、训练 token 数、参数量、prefill/decode 时间、实测峰值显存。','解释：若窗口只在远程检索下降，与可见范围假设一致；增加全局层后恢复，提供进一步证据。'],result:'只有结果支持的范围才写进结论。把纸面复杂度、实测速度和任务质量分开报告。'},[
  check('预算器显示 KV 减半，端到端推理是否一定快两倍？',['一定','不一定，还受计算、带宽、kernel 和其他层影响'],1,'字节预算是机制证据，不是计时结果。实际速度还受 FFN、投影、带宽、调度和 kernel 影响，需要在同一硬件与负载下测量。'),
  check('结构 A 参数更少但训练 token 更多，怎样报告？',['只写参数更少','同时列出数据、计算和质量，声明未完全匹配的因素'],1,'公平对照需要公开关键预算，不能把额外训练收益全部归因于结构。')
 ],['arch-kv-budget'],['systems','memory','omnifm'],['flash','paged','streaming','v3'])
];
